package com.z8dn.plugins.a2pt.settings

import com.z8dn.plugins.a2pt.AndroidViewBundle

import com.intellij.openapi.ui.DialogWrapper
import com.intellij.openapi.ui.ValidationInfo
import com.intellij.ui.ToolbarDecorator
import com.intellij.ui.components.JBLabel
import com.intellij.ui.components.JBTextField
import com.intellij.ui.table.JBTable
import com.intellij.util.ui.JBUI
import java.awt.Dimension
import java.awt.GridBagConstraints
import java.awt.GridBagLayout
import javax.swing.JComponent
import javax.swing.JOptionPane
import javax.swing.JPanel
import javax.swing.ListSelectionModel
import javax.swing.table.AbstractTableModel

/**
 * Dialog for adding or editing a custom file group with its patterns.
 */
class ProjectFileGroupDialog(
    existingGroup: ProjectFileGroup? = null
) : DialogWrapper(true) {

    private val groupNameField: JBTextField = JBTextField()
    private val patternsTable: JBTable
    private val patternsTableModel: PatternsTableModel

    init {
        title = if (existingGroup == null)
            AndroidViewBundle.message("dialog.ProjectFileGroup.Add.text")
        else
            AndroidViewBundle.message("dialog.ProjectFileGroup.Edit.text")

        patternsTableModel = PatternsTableModel()
        patternsTable = JBTable(patternsTableModel).apply {
            setShowGrid(true)
            setSelectionMode(ListSelectionModel.SINGLE_SELECTION)
            preferredScrollableViewportSize = Dimension(400, 150)
        }

        // Load existing data if editing
        existingGroup?.let {
            groupNameField.text = it.groupName
            patternsTableModel.setPatterns(it.patterns.toMutableList())
        }

        init()
    }

    override fun createCenterPanel(): JComponent {
        val panel = JPanel(GridBagLayout())
        val gbc = GridBagConstraints()
        gbc.gridx = 0
        gbc.gridy = 0
        gbc.anchor = GridBagConstraints.WEST
        gbc.fill = GridBagConstraints.HORIZONTAL
        gbc.insets = JBUI.insets(5)

        // Group name label
        panel.add(JBLabel(AndroidViewBundle.message("dialog.ProjectFileGroup.GroupName.text")), gbc)

        // Group name field
        gbc.gridy++
        gbc.weightx = 1.0
        groupNameField.preferredSize = Dimension(400, groupNameField.preferredSize.height)
        panel.add(groupNameField, gbc)

        // Patterns section label
        gbc.gridy++
        gbc.insets = JBUI.insets(15, 5, 5, 5)
        panel.add(JBLabel(AndroidViewBundle.message("dialog.ProjectFileGroup.Patterns.text")), gbc)

        // Patterns table with toolbar
        gbc.gridy++
        gbc.fill = GridBagConstraints.BOTH
        gbc.weighty = 1.0
        gbc.insets = JBUI.insets(5)

        val decorator = ToolbarDecorator.createDecorator(patternsTable)
            .setAddAction { addPattern() }
            .setRemoveAction { removePattern() }
            .setEditAction { editPattern() }
            .disableUpDownActions()

        panel.add(decorator.createPanel(), gbc)

        // Help text
        gbc.gridy++
        gbc.fill = GridBagConstraints.HORIZONTAL
        gbc.weighty = 0.0
        val helpLabel = JBLabel("<html><i>${AndroidViewBundle.message("dialog.ProjectFileGroup.Patterns.description")}</i></html>")
        panel.add(helpLabel, gbc)

        return panel
    }

    private fun addPattern() {
        val pattern = JOptionPane.showInputDialog(
            contentPanel,
            AndroidViewBundle.message("dialog.AddPattern.description"),
            AndroidViewBundle.message("dialog.AddPattern.text"),
            JOptionPane.PLAIN_MESSAGE
        )
        if (!pattern.isNullOrBlank()) {
            patternsTableModel.addPattern(pattern.trim())
        }
    }

    private fun removePattern() {
        val selectedRow = patternsTable.selectedRow
        if (selectedRow >= 0) {
            patternsTableModel.removePattern(selectedRow)
        }
    }

    private fun editPattern() {
        val selectedRow = patternsTable.selectedRow
        if (selectedRow >= 0) {
            val currentPattern = patternsTableModel.getPattern(selectedRow)
            val newPattern = JOptionPane.showInputDialog(
                contentPanel,
                AndroidViewBundle.message("dialog.EditPattern.description"),
                currentPattern
            )
            if (!newPattern.isNullOrBlank()) {
                patternsTableModel.updatePattern(selectedRow, newPattern.trim())
            }
        }
    }

    override fun doValidate(): ValidationInfo? {
        val groupName = groupNameField.text.trim()
        if (groupName.isEmpty()) {
            return ValidationInfo(AndroidViewBundle.message("dialog.Validation.GroupNameEmpty.text"), groupNameField)
        }

        val patterns = patternsTableModel.getPatterns()
        if (patterns.isEmpty()) {
            return ValidationInfo(AndroidViewBundle.message("dialog.Validation.PatternsEmpty.text"), patternsTable)
        }

        if (patterns.all { it.startsWith("!") }) {
            return ValidationInfo(AndroidViewBundle.message("dialog.Validation.NoInclusionPattern.text"), patternsTable)
        }

        return null
    }

    /**
     * Returns the configured ProjectFileGroup from the dialog.
     */
    fun getProjectFileGroup(): ProjectFileGroup {
        return ProjectFileGroup(
            groupName = groupNameField.text.trim(),
            patterns = patternsTableModel.getPatterns()
        )
    }

    /**
     * Table model for managing file patterns.
     */
    private class PatternsTableModel : AbstractTableModel() {
        private val patterns = mutableListOf<String>()

        override fun getRowCount(): Int = patterns.size

        override fun getColumnCount(): Int = 1

        override fun getColumnName(column: Int): String = AndroidViewBundle.message("dialog.ProjectFileGroup.Table.ColumnName.text")

        override fun getValueAt(rowIndex: Int, columnIndex: Int): String = patterns[rowIndex]

        fun addPattern(pattern: String) {
            patterns.add(pattern)
            fireTableRowsInserted(patterns.size - 1, patterns.size - 1)
        }

        fun removePattern(index: Int) {
            patterns.removeAt(index)
            fireTableRowsDeleted(index, index)
        }

        fun updatePattern(index: Int, pattern: String) {
            patterns[index] = pattern
            fireTableRowsUpdated(index, index)
        }

        fun getPattern(index: Int): String = patterns[index]

        fun getPatterns(): MutableList<String> = patterns.toMutableList()

        fun setPatterns(newPatterns: MutableList<String>) {
            patterns.clear()
            patterns.addAll(newPatterns)
            fireTableDataChanged()
        }
    }
}

package com.z8dn.plugins.a2pt.nodes

import com.intellij.icons.AllIcons
import com.intellij.ide.projectView.PresentationData
import com.intellij.ide.projectView.ViewSettings
import com.intellij.ide.util.treeView.AbstractTreeNode
import com.intellij.openapi.fileTypes.FileTypeManager
import com.intellij.openapi.module.ModuleUtilCore
import com.intellij.openapi.project.Project
import com.intellij.openapi.vfs.VirtualFile
import com.intellij.psi.PsiManager
import com.z8dn.plugins.a2pt.settings.ProjectFileGroup
import com.z8dn.plugins.a2pt.utils.AndroidViewNodeUtils
import com.z8dn.plugins.a2pt.utils.ProjectFileDisplayUtils
import javax.swing.Icon

/**
 * A top-level group node that displays project files matching a specific ProjectFileGroup.
 * This node appears at the project root level when showProjectFilesInModule is false.
 * Each instance represents one ProjectFileGroup with its groupName and patterns.
 */
class ProjectFileGroupNode(
    private val myProject: Project,
    private val settings: ViewSettings,
    private val fileGroup: ProjectFileGroup,
    private val allProjectFiles: List<Pair<VirtualFile, String>>
) : AbstractTreeNode<String>(myProject, fileGroup.groupName) {

    override fun getChildren(): Collection<AbstractTreeNode<*>> {
        // Only show children if showProjectFilesInModule is false
        if (AndroidViewNodeUtils.showProjectFilesInModule()) {
            return emptyList()
        }

        val result = mutableListOf<AbstractTreeNode<*>>()
        val psiManager = PsiManager.getInstance(myProject)

        for ((file, relativePath) in allProjectFiles) {
            // Only include files that match this group's patterns
            if (!AndroidViewNodeUtils.matchesPatterns(file.name, relativePath, fileGroup.patterns)) {
                continue
            }

            val psiFile = psiManager.findFile(file) ?: continue

            // Find which module contains this file (may be null for non-module folders)
            val module = ModuleUtilCore.findModuleForFile(file, myProject)
            val qualifier = if (module != null) {
                ProjectFileDisplayUtils.generateDisplayName(file, module)
            } else {
                file.parent?.name ?: relativePath
            }
            result.add(ProjectFileNode(myProject, psiFile, settings, qualifier, 10))
        }

        return result
    }

    override fun update(data: PresentationData) {
        data.presentableText = fileGroup.groupName
        data.setIcon(getGroupIcon())
    }

    /**
     * Determines the icon for this group based on the patterns.
     * - If there's only one non-exclusion pattern, use a file-type-specific icon
     * - Otherwise, use a generic folder icon
     */
    private fun getGroupIcon(): Icon {
        val inclusionPatterns = fileGroup.patterns.filter { !it.startsWith("!") }
        if (inclusionPatterns.size == 1) {
            val pattern = inclusionPatterns[0]
            val fileTypeManager = FileTypeManager.getInstance()

            // Handle wildcard patterns like "*.md"
            if (pattern.startsWith("*.")) {
                val extension = pattern.substring(2)
                val fileType = fileTypeManager.getFileTypeByExtension(extension)
                return fileType.icon ?: AllIcons.FileTypes.Text
            }

            // Handle exact filename patterns like "LICENSE"
            if (!pattern.contains("*") && !pattern.contains("/")) {
                val fileType = fileTypeManager.getFileTypeByFileName(pattern)
                return fileType.icon ?: AllIcons.FileTypes.Text
            }
        }

        // Default to folder icon for multiple patterns or complex wildcards
        return AllIcons.Nodes.Folder
    }
}

package com.z8dn.plugins.a2pt.settings

import com.intellij.openapi.application.ApplicationManager
import com.intellij.openapi.components.PersistentStateComponent
import com.intellij.openapi.components.State
import com.intellij.openapi.components.Storage
import com.intellij.openapi.components.RoamingType
import com.intellij.util.xmlb.XmlSerializerUtil

/**
 * Data class representing a project file group with its name and patterns.
 */
data class ProjectFileGroup(
    var groupName: String = "",
    var patterns: MutableList<String> = mutableListOf()
)

@State(
    name = "AndroidViewSettings",
    storages = [Storage("androidViewSettings.xml", roamingType = RoamingType.DEFAULT)]
)
class AndroidViewSettings : PersistentStateComponent<AndroidViewSettings> {

    var showBuildDirectory = false
    var projectFileGroups: MutableList<ProjectFileGroup> = mutableListOf()
    var showProjectFilesInModule = false

    companion object {
        @JvmStatic
        fun getInstance(): AndroidViewSettings {
            return ApplicationManager.getApplication()
                .getService(AndroidViewSettings::class.java)
        }
    }

    override fun getState(): AndroidViewSettings = this

    override fun loadState(state: AndroidViewSettings) {
        XmlSerializerUtil.copyBean(state, this)
    }
}

package com.z8dn.plugins.a2pt.settings

import com.z8dn.plugins.a2pt.AndroidViewBundle

import com.intellij.ide.projectView.ProjectView
import com.intellij.openapi.options.SearchableConfigurable
import com.intellij.openapi.project.ProjectManager
import com.intellij.ui.ToolbarDecorator
import com.intellij.ui.components.JBCheckBox
import com.intellij.ui.components.JBLabel
import com.intellij.ui.table.JBTable
import java.awt.BorderLayout
import java.awt.GridBagConstraints
import java.awt.GridBagLayout
import java.awt.Insets
import javax.swing.*
import javax.swing.table.AbstractTableModel

/**
 * Settings page for Advanced Android Project Tree.
 */
class AndroidViewSettingsConfigurable : SearchableConfigurable {

    private var panel: JPanel? = null
    private var showBuildDirectoryCheckBox: JBCheckBox? = null
    private var groupsTable: JBTable? = null
    private var groupsTableModel: ProjectFileGroupsTableModel? = null

    override fun getId(): String = "com.z8dn.plugins.a2pt.settings"

    override fun getDisplayName(): String = AndroidViewBundle.message("settings.DisplayName.text")

    override fun createComponent(): JComponent {
        val mainPanel = JPanel(GridBagLayout())
        mainPanel.border = BorderFactory.createEmptyBorder(10, 10, 10, 10)

        val gbc = GridBagConstraints()
        gbc.gridx = 0
        gbc.gridy = 0
        gbc.anchor = GridBagConstraints.WEST
        gbc.fill = GridBagConstraints.HORIZONTAL
        gbc.weightx = 1.0
        gbc.insets = Insets(5, 5, 5, 5)

        // Build directory checkbox
        showBuildDirectoryCheckBox = JBCheckBox(AndroidViewBundle.message("settings.ShowBuildDirectory.text")).apply {
            toolTipText = AndroidViewBundle.message("settings.ShowBuildDirectory.description")
        }
        mainPanel.add(showBuildDirectoryCheckBox, gbc)

        // Custom file groups table
        gbc.gridy++
        gbc.insets = Insets(15, 5, 5, 5)
        gbc.fill = GridBagConstraints.BOTH
        gbc.weighty = 1.0
        val tablePanel = createGroupsTablePanel()
        mainPanel.add(tablePanel, gbc)

        panel = mainPanel
        return mainPanel
    }

    private fun createGroupsTablePanel(): JPanel {
        val panel = JPanel(BorderLayout())
        panel.border = BorderFactory.createTitledBorder(AndroidViewBundle.message("settings.CustomFileGroups.text"))

        groupsTableModel = ProjectFileGroupsTableModel()
        groupsTable = JBTable(groupsTableModel).apply {
            setShowGrid(true)
            setSelectionMode(ListSelectionModel.SINGLE_SELECTION)
        }

        val decorator = ToolbarDecorator.createDecorator(groupsTable!!)
            .setAddAction { addGroup() }
            .setRemoveAction { removeGroup() }
            .setEditAction { editGroup() }

        panel.add(decorator.createPanel(), BorderLayout.CENTER)

        val helpLabel = JBLabel("<html><i>${AndroidViewBundle.message("settings.CustomFileGroups.description")}</i></html>")
        panel.add(helpLabel, BorderLayout.SOUTH)

        return panel
    }

    private fun addGroup() {
        val dialog = ProjectFileGroupDialog()
        if (dialog.showAndGet()) {
            groupsTableModel?.addGroup(dialog.getProjectFileGroup())
        }
    }

    private fun removeGroup() {
        val selectedRow = groupsTable?.selectedRow
        if (selectedRow != null && selectedRow >= 0) {
            groupsTableModel?.removeGroup(selectedRow)
        }
    }

    private fun editGroup() {
        val selectedRow = groupsTable?.selectedRow
        if (selectedRow != null && selectedRow >= 0) {
            val currentGroup = groupsTableModel?.getGroup(selectedRow) ?: return
            val dialog = ProjectFileGroupDialog(currentGroup)
            if (dialog.showAndGet()) {
                groupsTableModel?.updateGroup(selectedRow, dialog.getProjectFileGroup())
            }
        }
    }

    override fun isModified(): Boolean {
        val settings = AndroidViewSettings.getInstance()

        if (showBuildDirectoryCheckBox?.isSelected != settings.showBuildDirectory) {
            return true
        }

        val currentGroups = groupsTableModel?.getGroups() ?: emptyList()
        return currentGroups != settings.projectFileGroups
    }

    override fun apply() {
        val settings = AndroidViewSettings.getInstance()

        settings.showBuildDirectory = showBuildDirectoryCheckBox?.isSelected ?: false

        // Clear and rebuild the groups list to ensure proper change detection
        settings.projectFileGroups.clear()
        groupsTableModel?.getGroups()?.forEach { group ->
            settings.projectFileGroups.add(ProjectFileGroup(group.groupName, group.patterns.toMutableList()))
        }

        // Refresh all open projects to reflect the changes
        // Do this synchronously to ensure settings are applied before refresh
        ProjectManager.getInstance().openProjects
            .filter { !it.isDisposed }
            .forEach { project ->
                ProjectView.getInstance(project).currentProjectViewPane?.updateFromRoot(true)
            }
    }

    override fun reset() {
        val settings = AndroidViewSettings.getInstance()

        showBuildDirectoryCheckBox?.isSelected = settings.showBuildDirectory
        groupsTableModel?.setGroups(settings.projectFileGroups.map {
            ProjectFileGroup(it.groupName, it.patterns.toMutableList())
        })
    }

    /**
     * Table model for managing custom file groups.
     */
    private class ProjectFileGroupsTableModel : AbstractTableModel() {
        private val groups = mutableListOf<ProjectFileGroup>()

        override fun getRowCount(): Int = groups.size

        override fun getColumnCount(): Int = 2

        override fun getColumnName(column: Int): String = when (column) {
            0 -> AndroidViewBundle.message("settings.Table.ColumnName.groupName")
            1 -> AndroidViewBundle.message("settings.Table.ColumnName.patterns")
            else -> ""
        }

        override fun getValueAt(rowIndex: Int, columnIndex: Int): Any {
            val group = groups[rowIndex]
            return when (columnIndex) {
                0 -> group.groupName
                1 -> group.patterns.joinToString(", ")
                else -> ""
            }
        }

        fun addGroup(group: ProjectFileGroup) {
            groups.add(group)
            fireTableRowsInserted(groups.size - 1, groups.size - 1)
        }

        fun removeGroup(index: Int) {
            groups.removeAt(index)
            fireTableRowsDeleted(index, index)
        }

        fun updateGroup(index: Int, group: ProjectFileGroup) {
            groups[index] = group
            fireTableRowsUpdated(index, index)
        }

        fun getGroup(index: Int): ProjectFileGroup = groups[index]

        fun getGroups(): List<ProjectFileGroup> = groups.toList()

        fun setGroups(newGroups: List<ProjectFileGroup>) {
            groups.clear()
            groups.addAll(newGroups)
            fireTableDataChanged()
        }
    }
}

