17	 * Represents a scope based on project file groups from settings
18	 */
19	class ProjectFileGroupScope private constructor(
20	    private val myProject: Project,
21	    displayName: String,
22	    private val fileGroup: ProjectFileGroup?,
23	    private val isParent: Boolean
24	) : RangeBasedLocalSearchScope(displayName, false), WeighedItem {
25	
26	    companion object {
27	        /**
28	         * Creates a child scope for a specific project file group
29	         */
30	        fun createFileGroupScope(project: Project, fileGroup: ProjectFileGroup): ProjectFileGroupScope {
31	            return ProjectFileGroupScope(
32	                project,
33	                fileGroup.groupName,
34	                fileGroup,
35	                false
36	            )
37	        }
38	
39	        private fun matchesAnyFileGroup(file: VirtualFile): Boolean {
40	            val settings = AndroidViewSettings.getInstance()
41	            return settings.projectFileGroups.any { group ->
42	                matchesFileGroup(file, group)
43	            }
44	        }
45	
46	        private fun matchesFileGroup(file: VirtualFile, fileGroup: ProjectFileGroup): Boolean {
47	            return fileGroup.patterns.any { pattern ->
48	                matchesPattern(file, pattern)
49	            }
50	        }
51	
52	        private fun matchesPattern(file: VirtualFile, pattern: String): Boolean {
53	            // Convert glob pattern to regex
54	            val regexPattern = pattern
55	                .replace(".", "\\.")
56	                .replace("*", ".*")
57	                .replace("?", ".")
58	
59	            val regex = Regex(regexPattern, RegexOption.IGNORE_CASE)
60	            return regex.matches(file.name) || regex.containsMatchIn(file.path)
61	        }
62	    }
63	
64	    private val myVirtualFiles: Array<VirtualFile> by lazy {
65	        val allFiles = mutableListOf<VirtualFile>()
66	        // Collect files from project
67	        if (fileGroup != null) {
68	            // Child scope - filter by specific file group
69	            collectFiles(myProject, allFiles) { file -> matchesFileGroup(file, fileGroup) }
70	        } else {
71	            // Parent scope - all project file groups
72	            collectFiles(myProject, allFiles) { file -> matchesAnyFileGroup(file) }
73	        }
74	        allFiles.toTypedArray()
75	    }
76	
77	    private fun collectFiles(project: Project, result: MutableList<VirtualFile>, filter: (VirtualFile) -> Boolean) {
78	        val projectBaseDir = project.basePath?.let { com.intellij.openapi.vfs.LocalFileSystem.getInstance().findFileByPath(it) } ?: return
79	        collectFilesRecursively(projectBaseDir, result, filter)
80	    }
81	
82	    private fun collectFilesRecursively(directory: VirtualFile, result: MutableList<VirtualFile>, filter: (VirtualFile) -> Boolean) {
